window.FILM_WORK_PROMPTS={"work_id":"src-fd85e9f5d6fef5ec","records":[{"work_id":"src-fd85e9f5d6fef5ec","frame_id":"FG-46443e7547509899","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (1223).jpg","source_page":"https://film-grab.com/2013/11/10/time-of-the-wolf/","scene":"昏暗的室外空地，两名人物站在一辆自行车旁，背景是带有两扇窗户的浅色建筑墙面，画面右侧被大面积黑色栅栏遮挡。","analysis":"构图呈现强烈的明暗对比，画面右侧约三分之一被黑色垂直栅栏占据，形成前景遮挡。左侧可见两名人物，左侧人物全身可见，站立在自行车旁；右侧人物仅上半身清晰，身形较小。背景建筑墙面占据中景，光线极暗，整体色调偏冷灰，仅墙面有微弱反光，人物与自行车呈剪影状，细节模糊。","prompt":"昏暗的室外场景，画面右侧前景被黑色垂直栅栏遮挡，占据约三分之一宽度。左侧中景处，两名人物站在一辆自行车旁，左侧人物全身可见，深色衣物，站立姿态；右侧人物身形较小，仅上半身清晰，深色衣物。背景是一面浅色建筑外墙，墙上有两扇深色矩形窗户，墙面有微弱反光。整体光线极暗，色调偏冷灰，人物与自行车呈剪影状，细节模糊，地面平坦，氛围压抑。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T12:14:26+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (1223).jpg","observed_dimensions":[1012,435],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":0.276,"observed_resolution":"normal","observation_limits":[],"id":"VP-61b4b2219fec468d","origin":"visual"},{"work_id":"src-fd85e9f5d6fef5ec","frame_id":"FG-75bfb98f60e22742","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (1248).jpg","source_page":"https://film-grab.com/2013/11/10/time-of-the-wolf/","scene":"灰白天空下，一名穿深色外套的人物站在土坡草坡上，背对镜头。右侧前景有枯枝灌木，远处可见电线杆与树木，地面散落着红色与白色不明物体。","analysis":"画面采用广角视野，人物位于画面中左部，全身可见但身形较小，与广阔环境形成对比。右侧前景的枯枝占据约三分之一画面，形成视觉引导。光线为阴天漫射光，无强烈阴影，整体色调偏冷灰绿，色彩饱和度低，呈现出一种荒凉、静谧的视觉氛围。","prompt":"灰白阴沉的天空下，一片荒凉的土坡草地。一名身穿深色厚外套、深色长裤的人物背对镜头，独自站在画面中左侧的坡地上，身形在广阔环境中显得渺小。人物右侧的坡面上散落着红色和白色的不明物体。画面右侧前景是一丛高大的枯枝灌木，枝条稀疏，部分遮挡视线。远处地平线平坦，可见一根竖立的电线杆和一棵孤立的树木。整体光线为阴天漫射光，无直射阳光，色调以灰绿、土黄和冷灰为主，画面颗粒感明显，呈现出一种压抑、寂寥的野外氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T12:14:34+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (1248).jpg","observed_dimensions":[1012,435],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":0.496,"observed_resolution":"normal","observation_limits":[],"id":"VP-dd86b4a0f57f5350","origin":"visual"},{"work_id":"src-fd85e9f5d6fef5ec","frame_id":"FG-f22262760c10efd6","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (1245).jpg","source_page":"https://film-grab.com/2013/11/10/time-of-the-wolf/","scene":"双手持握一张泛黄信纸，右手握笔正在书写，背景为模糊的浅色桌面，画面聚焦于手写字迹与手部动作。","analysis":"构图紧凑，主体为占据画面大部分面积的纸张与双手。人物仅可见双手及部分手指，左手在左侧边缘捏住纸张，右手在右侧握笔书写。视角为俯视，光线柔和均匀，纸张呈现陈旧的米黄色调，手写字迹清晰，背景虚化，明暗对比自然，无强烈阴影。","prompt":"俯视视角的写实画面，主体是一张泛黄的信纸，上面写有清晰的法文手写字迹。画面左侧可见一只手的拇指和食指捏住纸张边缘，右侧一只手握着一支深色笔杆的笔，笔尖触纸正在书写。背景为模糊的浅色平面，光线柔和自然，色调偏暖黄，呈现出一种安静、专注的书写氛围，细节丰富，景深较浅，焦点集中在文字与手部动作上。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T12:14:40+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (1245).jpg","observed_dimensions":[1012,435],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":0.543,"observed_resolution":"normal","observation_limits":[],"id":"VP-c1b3565bb189cfcc","origin":"visual"},{"work_id":"src-fd85e9f5d6fef5ec","frame_id":"FG-e37b364b10fa8427","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (1220).jpg","source_page":"https://film-grab.com/2013/11/10/time-of-the-wolf/","scene":"深褐色马匹侧卧于泥土地面，一人站立俯身，手持刀具在颈部进行切割，切口处有暗红色液体流出。","analysis":"画面采用俯视视角，主体为占据画面下半部的大面积马匹躯体。人物仅可见躯干中段至手部，穿着灰色长袖衣物，双手分别按在马背与颈部。光线为自然散射光，色调偏冷且低饱和，泥土的粗糙质感与马匹皮毛的湿润感形成对比，暗红色液体在深色背景中形成视觉焦点。","prompt":"俯视视角的写实画面，深褐色马匹侧卧在粗糙的深褐色泥土地面上，占据画面大部分空间。一名身穿灰色长袖衣物的人物站立在马身旁，仅可见躯干中段及双手，左手按在马背上方，右手持一把带木柄的刀具在马颈部进行切割。切口处流出暗红色液体，顺着马身流向地面形成一滩深色液体。环境光线为阴天的自然散射光，整体色调低沉、偏冷且饱和度低，强调泥土的颗粒感与马匹皮毛的质感，画面呈现出一种冷静而残酷的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T12:14:48+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (1220).jpg","observed_dimensions":[1012,435],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":0.513,"observed_resolution":"normal","observation_limits":[],"id":"VP-076b25b0c6d8f8bd","origin":"visual"},{"work_id":"src-fd85e9f5d6fef5ec","frame_id":"FG-6cc0cf86b3559069","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (1119).jpg","source_page":"https://film-grab.com/2013/11/10/time-of-the-wolf/","scene":"画面主体为一名年轻女孩的面部特写，她正躺着，头部枕在深色织物上。背景几乎完全隐没在黑暗中，仅能隐约辨认出左侧有一块灰白色的枕头或布料区域。","analysis":"构图极度紧凑，女孩面部占据画面中心及右侧大部分区域，左侧留有大面积黑色负空间。人物仅面部及额头部分可见，身体其余部分不可见。拍摄视角为轻微俯视。光线极暗，仅微弱侧光勾勒出面部轮廓，形成强烈的明暗对比，大部分细节隐藏在阴影中，色彩层次单一，以黑灰色调为主。","prompt":"这是一张极度昏暗的人物面部特写画面。一名年轻女孩正躺着，头部枕在深色织物上，面部朝向画面左上方。女孩留着深色刘海，眼神平静地望向侧方，面部皮肤在微弱光线下呈现出苍白的质感，鼻梁处有一道深色的阴影或线条。画面左侧背景是一片模糊的灰白色枕头区域，其余部分完全被浓重的黑色阴影吞噬。整体光线极弱，仅有一束微弱的光源照亮女孩面部，营造出压抑、静谧且神秘的视觉氛围，色彩以黑灰色调为主，对比度极高。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T12:14:55+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (1119).jpg","observed_dimensions":[1012,435],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":0.233,"observed_resolution":"normal","observation_limits":[],"id":"VP-16370d7e3ddd375d","origin":"visual"},{"work_id":"src-fd85e9f5d6fef5ec","frame_id":"FG-4163c35a297559ed","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (1223).jpg","source_page":"https://film-grab.com/2013/11/10/time-of-the-wolf/","scene":"夜间昏暗的街道，三人并排站立。中间人物扶着自行车，左右各有一人，背景可见房屋轮廓与停放的车辆。","analysis":"画面采用平视视角，整体曝光极低，呈现暗调。三人位于画面中景，全身可见。中间人物体型最大，占据视觉中心，左右人物身形较小。光线微弱，仅能辨识人物轮廓及衣物色块，背景细节隐没在黑暗中，明暗对比强烈。","prompt":"夜间低照度街道场景，三人并排站立。中间人物身穿深褐色厚外套，双手扶着自行车车把，车前挂着彩色条纹袋子，肩背斜挎包。左侧人物穿黑色外套，右侧人物穿暗红色羽绒服。背景是模糊的房屋建筑与停放的汽车，环境昏暗，光线微弱，仅能看清人物轮廓与衣物颜色，整体色调阴冷压抑。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T18:19:28+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (1223).jpg","observed_dimensions":[1012,435],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":0.464,"observed_resolution":"normal","observation_limits":[],"id":"VP-bfcb015d03679d68","origin":"visual"},{"work_id":"src-fd85e9f5d6fef5ec","frame_id":"FG-255ca3778205d2bf","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (1248).jpg","source_page":"https://film-grab.com/2013/11/10/time-of-the-wolf/","scene":"一名身穿深红褐色厚棉服的短发人物侧身坐在草地上，双臂环抱，神情低落。背景远处有一列长长的白色罐车停靠在铁轨上，周围是荒凉的野外环境。","analysis":"画面采用侧向构图，人物占据左侧前景，身体呈蜷缩坐姿，仅可见上半身及大腿部分。背景中一列白色罐车横向延伸，与前景人物形成明显的空间纵深对比。光线为柔和的自然散射光，整体色调偏冷且饱和度低，深红褐色衣物与灰绿色草地、白色车厢形成色彩层次。","prompt":"写实风格电影静帧，画面左侧前景是一名留着棕色短发的少年，身穿深红褐色绗缝厚棉服，侧身蜷缩坐在草地上，双臂环抱在胸前，神情显得孤独而低落。左下角可见一辆自行车的局部车轮和红色挡泥板。背景是一片开阔的野外草地，远处铁轨上停靠着一长列白色的圆柱形罐车，延伸至画面右侧。整体光线为阴天柔和的自然光，色调偏冷，以灰绿、土黄和深红褐色为主，营造出一种荒凉、静谧且略带压抑的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T18:19:36+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (1248).jpg","observed_dimensions":[1012,435],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":0.507,"observed_resolution":"normal","observation_limits":[],"id":"VP-a7319b2cd79cae7e","origin":"visual"},{"work_id":"src-fd85e9f5d6fef5ec","frame_id":"FG-0919f430b4f0f7fe","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (1245).jpg","source_page":"https://film-grab.com/2013/11/10/time-of-the-wolf/","scene":"画面中央矗立着一座深灰色的塔状结构，底部呈宽大的圆形基座，向上逐渐收窄。背景是灰白色的墙面，上方垂下多条模糊的深色条痕，前景为黄褐色的平坦地面。","analysis":"构图采用中心对称，主体位于画面正中。塔状物占据画面垂直方向的大部分空间，底部与地面接触。背景墙面占据上方约三分之二区域，分布着垂直的深色污渍或阴影。前景地面呈横向带状，颜色较浅。整体光线均匀柔和，无明显强光源方向，色彩以低饱和度的灰、褐、米色为主，呈现出一种陈旧、静谧的视觉质感。","prompt":"这是一幅色调陈旧的写实画面，中央矗立着一座深灰色的塔状物体，底部宽大呈圆形，向上收窄，轮廓略显模糊。背景是一面灰白色的墙壁，上方垂下多条垂直的深色条痕，如同雨渍或阴影。前景是黄褐色的平坦地面，带有斑驳的纹理。整体光线柔和均匀，色彩饱和度低，以灰色和土黄色为主，营造出一种静谧、压抑且略带神秘的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T18:19:44+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (1245).jpg","observed_dimensions":[1012,435],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":0.51,"observed_resolution":"normal","observation_limits":[],"id":"VP-d7e003ccbbbc7039","origin":"visual"},{"work_id":"src-fd85e9f5d6fef5ec","frame_id":"FG-a243a5318a45a665","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (1213).jpg","source_page":"https://film-grab.com/2013/11/10/time-of-the-wolf/","scene":"画面主体为地面，左侧是灰白色的沙土路面，右侧是深绿色的杂草丛，两者呈对角线分布，光线昏暗，无可见人物。","analysis":"构图采用对角线分割，左下至右上为沙土，其余为草地。视角为高角度俯拍，地面纹理清晰可见。整体色调偏暗，呈低饱和度的灰绿与土黄色，光线平淡无强烈阴影，画面质感粗糙，呈现出一种荒凉、静谧的视觉氛围。","prompt":"这是一张高角度俯拍的地面特写，画面被一条不规则的对角线分割。左下部分是大面积的灰白色沙土路面，表面散布着细小的碎石和颗粒，质感干燥粗糙。右上部分则是深绿色的杂草丛，草叶稀疏且杂乱，夹杂着枯黄的草茎。整体光线昏暗柔和，色彩饱和度极低，呈现出一种阴郁、荒凉的色调。画面中没有任何人物或大型物体，仅展示了自然环境的局部细节，营造出一种静谧而压抑的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T18:19:51+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (1213).jpg","observed_dimensions":[1012,435],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":0.526,"observed_resolution":"normal","observation_limits":[],"id":"VP-fe3fea12130e9fed","origin":"visual"},{"work_id":"src-fd85e9f5d6fef5ec","frame_id":"FG-8b08853fb46ff18f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (1106).jpg","source_page":"https://film-grab.com/2013/11/10/time-of-the-wolf/","scene":"极暗夜色中，一条碎石铁轨向远处延伸，中央站立着一个人影。左侧可见高架圆柱形储罐，右侧是巨大的深色建筑墙体，远处背景隐约可见拱形结构。","analysis":"构图采用中心对称，铁轨线条汇聚于画面深处。人物位于画面中央，呈站立姿态，全身轮廓可见但细节隐没在黑暗中，相对于两侧巨大的工业设施显得十分渺小。画面整体曝光极低，仅能辨识出左侧储罐的浅色轮廓和右侧建筑的微弱反光，光色层次单一，呈现压抑的冷暗色调。","prompt":"极暗的夜间工业场景，画面中心是一条向远处延伸的碎石铁轨，铁轨中央站立着一个黑色人影，全身轮廓可见但细节模糊。画面左侧矗立着两个高架的圆柱形储罐，右侧是巨大的深色建筑墙体，远处背景隐约可见拱形结构。整体光线极弱，仅能辨识出左侧储罐的浅色轮廓和右侧建筑的微弱反光，环境显得空旷、压抑且寂静。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T18:19:57+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (1106).jpg","observed_dimensions":[1012,435],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":0.34,"observed_resolution":"normal","observation_limits":[],"id":"VP-8291df436fe454bb","origin":"visual"}]};